/// 📬️ Runs one native child reply to completion inside the caller's own action; a pending reply is a fixture fault.
pub(crate) fn settle_reply<T,E:From<ValueError>>(effect:&mut RetainedAllocationEffect<'_>,call:impl for<'r,'e,'a> FnOnce(&'e mut RetainedAllocationEffect<'a>,OriginalEffectReply<'r,T,E>)->Result<OriginalEffectReplyComplete<'r,T,E>,ValueError>)->RetainedWorkOutcome<T,E>{
 let before=effect.performed_work();let mut slot=None;
 let settled=(||->Result<Result<T,E>,ValueError>{let done=call(&mut *effect,OriginalEffectReply::borrow(&mut slot)?)?;drop(done);slot.take().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"fixture reply stayed pending"))})();
 let work=effect.performed_work().saturating_sub(before);RetainedWorkOutcome{result:match settled{Ok(result)=>result,Err(error)=>Err(error.into())},work}
}
/// 🎟️ Funds the complete admission quote of one value, copy included, on top of the caller's authority.
pub(crate) fn admit_funded<T:RetireOwned+Send+Sync+'static>(value:T,issuer:SharedIssuer<T>,mut grant:RetainedCloneGrant)->RetainedWorkOutcome<(SealedShared<T>,RetainedCloneProgress),(ValueError,T)>{let d=SealedShared::<T>::source_admission_demand().unwrap();grant.maximum_copy_bytes=grant.maximum_copy_bytes.max(d.copy_bytes);let mut input=Some(value);let mut output=None;let mut issuer=Some(issuer);let mut total=RetainedCloneProgress::default();let mut work=0;for _ in 0..64{let turn=effect::run(grant,|effect|SealedShared::admit_from(&mut input,issuer.take().unwrap_or_else(SharedIssuer::owned),&mut output,effect));work+=turn.work;match turn.result{Ok(step)=>total=total.checked_add(step.progress()).unwrap(),Err(error)=>return RetainedWorkOutcome{result:Err((error,input.take().expect("refused admission keeps its value"))),work}}if let Some(sealed)=output.take(){return RetainedWorkOutcome{result:Ok((sealed,total)),work}}}RetainedWorkOutcome{result:Err((ValueError::invariant("sealed admission is not funded"),input.take().expect("unfunded admission keeps its value"))),work}}
