pub(crate) fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
pub(crate) fn heap<T>(run:impl FnOnce()->T)->(T,(usize,usize)){observe_retirement_allocations(run)}
pub(crate) fn exact<T>(run:impl FnOnce()->T,receipt:impl FnOnce(&T)->RetainedCloneProgress)->(T,usize,usize){let(value,bytes)=heap(run);let p=receipt(&value);assert_eq!(bytes,(p.retained_capacity_bytes,p.released_bytes));(value,bytes.0,bytes.1)}
pub(crate) fn denies(d:RetirementDemand)->Vec<RetainedCloneGrant>{let g=grant(d);let mut rows=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{rows.push(RetainedCloneGrant{maximum_copy_bytes:0,..g});}if d.capacity_bytes>0{rows.push(RetainedCloneGrant{maximum_capacity_bytes:0,..g});}if d.release_bytes>0{rows.push(RetainedCloneGrant{maximum_release_bytes:0,..g});}if d.depth>0{rows.push(RetainedCloneGrant{maximum_depth:0,..g});}rows}
pub(crate) fn fixture_bank()->semio_framework_value_testing_effect_bank::EffectBank{semio_framework_value_testing_effect_bank::EffectBank::new(semio_framework_value_testing_effect_bank::Wallet::new(RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<40,maximum_capacity_bytes:1<<40,maximum_release_bytes:1<<40,maximum_depth:1<<10},1<<40))}
