pub(crate) struct Raw<X>(*mut X);unsafe impl<X> Send for Raw<X>{}
pub(crate) fn turn_ref<X:'static>(owner:&mut X,grant:RetainedCloneGrant,mut call:impl for<'r,'e> FnMut(&mut X,bool,&mut RetainedAllocationEffect<'e>,Reply<'r>)->Result<Done<'r>,ValueError>)->(Result<RetainedCloneStep,OriginalRetirementFailure>,(usize,usize),u128){let(_,answer,heap,work)=support::driver::turn(Raw(owner as*mut X),grant,|raw,recover,effect,reply|call(unsafe{&mut*raw.0},recover,effect,reply));(answer,heap,work)}
/// 🔁️ Closes any reply-shaped owner through actual original turns and returns its born and released heap totals; denied grants must change nothing when `deny` is set.
pub(crate) fn close_loop<X:'static>(owner:&mut X,body:usize,deny:bool,empty:impl Fn(&X)->bool,demand:impl Fn(&X)->RetirementDemand,call:impl for<'r,'e> Fn(&mut X,bool,&mut RetainedAllocationEffect<'e>,Reply<'r>)->Result<Done<'r>,ValueError>)->(usize,usize){
 let(mut born,mut released)=(0,0);let mut close_work=close_work_policy::Work::new();
 while !empty(owner){let d=demand(owner);assert!(d.copy_bytes<=body,"selected close quote of {} exceeds its authored body: {d:?} > {body}",std::any::type_name::<X>());
  if deny{for denied in denies(d){let(answer,bytes,work)=turn_ref(owner,denied,|x,recover,effect,reply|call(x,recover,effect,reply));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(bytes,(0,0));assert_eq!(work,0);assert_eq!(demand(owner),d);}}
  let issued=RetainedCloneGrant{maximum_copy_bytes:body,..grant(d)};let(answer,bytes,_)=turn_ref(owner,issued,|x,recover,effect,reply|call(x,recover,effect,reply));let progress=answer.unwrap().progress();assert_eq!(bytes,(progress.retained_capacity_bytes,progress.released_bytes));born+=bytes.0;released+=bytes.1;assert!(progress.fits(issued));
  close_work.observe(progress==Default::default()&&!empty(owner)&&demand(owner)==d);}
 (born,released)
}
pub(crate) fn close_source<T:RetireOwned+Sync+'static>(source:&mut RetainedCloneSource<T>){close_loop(source,4096,false,|s|s.terminal_is_empty(),|s|s.next_close_demand(4096).unwrap(),|s,recover,effect,reply|if recover{s.recover_close_into(4096,effect,reply)}else{s.close_into(4096,effect,reply)});}
pub(crate) fn retirement_budget()->(usize,usize){*RETIREMENT_BUDGET.get_or_init(||{let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🔑️named/📇️index/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let rows=fixture["lengths"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize).max().unwrap();let policy=&fixture["retirementWork"];let maximum=rows.checked_mul(policy["turnsPerRow"].as_u64().unwrap()as usize).and_then(|turns|turns.checked_add(policy["fixedTurns"].as_u64().unwrap()as usize)).unwrap();(maximum,policy["maximumIdleTurns"].as_u64().unwrap()as usize)})}
pub(crate) static RETIREMENT_BUDGET:std::sync::OnceLock<(usize,usize)>=std::sync::OnceLock::new();
pub(crate) fn retirement_turn(turns:&mut usize,idle:&mut usize,unchanged:bool){let(maximum,idle_limit)=retirement_budget();*turns=turns.checked_add(1).unwrap();*idle=if unchanged{idle.checked_add(1).unwrap()}else{0};assert!(*turns<maximum,"named retirement exceeded its fixture-scaled work budget");assert!(*idle<idle_limit,"named retirement repeated an unchanged public receipt and selected quote");}
pub(crate) fn drain<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();close_loop(&mut owner,4096,false,|o|o.terminal_is_empty(),|o|o.selected_demand(4096).unwrap(),|o,recover,effect,reply|if recover{o.recover_step_into(4096,effect,reply)}else{o.step_into(4096,effect,reply)});}
pub(crate) fn close_preparation(owner:&mut NamedKeyIndexPreparation,births:usize,releases:usize){owner.begin_close();let(b,r)=close_loop(owner,1<<16,true,|o|o.terminal_is_empty(),|o|o.close_demand(1<<16).unwrap(),|o,recover,effect,reply|if recover{o.recover_close_into(1<<16,effect,reply)}else{o.close_into(1<<16,effect,reply)});assert_eq!(births+b,releases+r);assert_eq!(heap(||{}).1,(0,0));}
pub(crate) fn close_index(index:&mut AdmittedNamedKeyIndex)->(usize,usize){index.begin_close();close_loop(index,4096,true,|o|o.terminal_is_empty(),|o|o.close_demand(4096).unwrap(),|o,recover,effect,reply|if recover{o.recover_close_into(4096,effect,reply)}else{o.close_into(4096,effect,reply)})}
pub(crate) fn close_plan(plan:&mut NamedEditPlan){plan.begin_close();close_loop(plan,1<<16,true,|o|o.terminal_is_empty(),|o|o.close_demand(1<<16).unwrap(),|o,recover,effect,reply|if recover{o.recover_close_into(1<<16,effect,reply)}else{o.close_into(1<<16,effect,reply)});}
pub(crate) fn admit<S:NamedRankedSource>(source:&S)->AdmittedNamedKeyIndex{let mut owner=NamedKeyIndexPreparation::new(source.len(),grant(NamedKeyIndexPreparation::constructor_demand())).result.unwrap().unwrap();loop{let d=owner.demand(source,4096).unwrap();let(s,..)=advance_exact(&mut owner,source,grant(d));if matches!(s,NamedEditStep::Admitted(_)){break;}assert!(!matches!(s,NamedEditStep::Refused(..)));}let d=owner.take_demand().unwrap();let((index,_),..)=exact(||owner.take(grant(d)).result.unwrap().unwrap(),|(_,p)|*p);owner.begin_close();assert!(owner.terminal_is_empty());assert_eq!(heap(||drop(owner)).1,(0,0));index}
pub(crate) struct Query<'a>{len:usize,key:&'a str}
impl NamedEditSource for Query<'_>{
 fn shape(&self)->IndexedEditShape{IndexedEditShape{base_len:self.len,removed:0,modified:1,added:0}}
 fn key_demand(&self,lane:NamedEditLane,ordinal:usize)->Result<RetirementDemand,ValueError>{if lane!=NamedEditLane::Modified||ordinal!=0{return Err(ValueError::invariant("unexpected key lane"));}Ok(contiguous_named_key_demand(self))}
 fn observe_key(&self,lane:NamedEditLane,ordinal:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<(&str,RetainedCloneProgress)>>{let d=match self.key_demand(lane,ordinal){Ok(d)=>d,Err(error)=>return RetainedWorkOutcome{result:Err(error),work:0}};observe_contiguous_named_key(d,g,||RetainedWorkOutcome{result:Ok(self.key),work:1})}
 fn added_index(&self,_:usize)->RetainedWorkOutcome<usize>{unreachable!("original named lookup has no additions")}
}
pub(crate) fn lookup<S:NamedRankedSource>(source:&S,index:&AdmittedNamedKeyIndex,key:&str)->(Option<usize>,usize){let d=index.project_demand(source).unwrap();let mut projected=None;for _ in 0..2{let(step,..)=exact(||effect::settle(grant(d),|effect|index.project(source,&mut projected,effect)).result.unwrap(),|step|step.progress());assert!(step.progress().fits(grant(d)));}let mut slot=Some(projected.unwrap());assert!(slot.as_ref().unwrap().ready());let d=NamedEditPlan::indexed_constructor_demand();let mut plan=NamedEditPlan::new_indexed(Query{len:source.len(),key}.shape(),&mut slot,grant(d)).result.unwrap().unwrap();assert!(slot.is_none());let query=Query{len:source.len(),key};let input=IndexedNamedSource::new(source,&query,index).unwrap();let mut capacity=0;while !plan.settled(){let d=plan.demand(&input,4096).unwrap();for denied in denies(d){let(s,bytes)=heap(||effect::settle(denied,|effect|plan.advance(&input,effect)).result.unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(bytes,(0,0));assert_eq!(plan.demand(&input,4096).unwrap(),d);}let(s,b,..)=exact(||effect::settle(grant(d),|effect|plan.advance(&input,effect)).result.unwrap(),|s|s.progress());capacity+=b;assert!(s.progress().copied_bytes<=d.copy_bytes);}let result=if plan.ready(){let d=plan.modified_index_demand(0).unwrap();let((rank,p),bytes)=heap(||plan.observe_modified_index(0,grant(d)).result.unwrap().unwrap());assert_eq!(bytes,(0,0));assert_eq!(p.copied_bytes,d.copy_bytes);Some(rank)}else{assert_eq!(plan.fault(),Some(NamedEditFault::MissingModified));None};close_plan(&mut plan);assert_eq!(heap(||drop(plan)).1,(0,0));(result,capacity)}
pub(crate) fn sync(effect:RetainedCloneGrant,call:impl for<'r,'e> FnOnce(&mut RetainedAllocationEffect<'e>,OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>)->RetainedCloneStep{effect::run(effect,|e|settle_reply(e,call)).result.unwrap()}
pub(crate) fn persistent(keys:impl IntoIterator<Item=String>,len:usize)->PersistentList<Row>{let mut builder=PersistentListBuilder::new(len);for text in keys{while !builder.accepts_row(){let d=builder.demand().unwrap();sync(grant(d),|e,r|builder.advance_into(e,r));}let mut row=Some(admit_funded(Row{key:text},SharedIssuer::owned(),grant(RetirementDemand{capacity_bytes:SealedShared::<Row>::birth_bytes(),depth:1,..Default::default()})).result.map_err(|(e,_)|e).unwrap().0);let d=builder.adopt_demand().unwrap();sync(grant(d),|e,r|builder.adopt_into(&mut row,e,r));}let d=builder.finish_demand().unwrap();sync(grant(d),|e,r|builder.finish_into(e,r));while !builder.output_ready(){let d=builder.demand().unwrap();sync(grant(d),|e,r|builder.advance_into(e,r));}let d=builder.take_demand().unwrap();let mut root=None;sync(grant(d),|e,r|builder.take_into(&mut root,e,r));let root=root.unwrap();effect::run(grant(builder.begin_close_demand()),|e|builder.begin_close_paid(e)).result.unwrap();close_loop(&mut builder,4096,false,|o|o.terminal_is_empty(),|o|o.close_demand(4096).unwrap(),|o,recover,effect,reply|if recover{o.recover_close_into(4096,effect,reply)}else{o.close_into(4096,effect,reply)});root}

/// 🔁️ One preparation advance inside an actual original invocation, because its nested plan close is reply-shaped.
pub(crate) fn prepare_turn<S:NamedRankedSource>(owner:&mut NamedKeyIndexPreparation,source:&S,grant:RetainedCloneGrant)->(Result<NamedEditStep,OriginalRetirementFailure>,(usize,usize),u128){let mut captured=None;let(_,heap,work)=turn_ref(owner,grant,|x,_,effect,reply|{captured=Some(x.advance(source,effect).result);Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))});(captured.expect("preparation advance ran"),heap,work)}
pub(crate) fn advance_denied<S:NamedRankedSource>(owner:&mut NamedKeyIndexPreparation,source:&S,denied:RetainedCloneGrant)->(NamedEditStep,(usize,usize)){let(step,heap,_)=prepare_turn(owner,source,denied);(step.unwrap(),heap)}
pub(crate) fn advance_exact<S:NamedRankedSource>(owner:&mut NamedKeyIndexPreparation,source:&S,grant:RetainedCloneGrant)->(NamedEditStep,usize,usize){let(step,heap,_)=prepare_turn(owner,source,grant);let step=step.unwrap();let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));(step,heap.0,heap.1)}
/// 🔁️ Runs one outcome-shaped producer action inside an actual original invocation and observes its heap and Work.
pub(crate) fn outcome_turn<X:'static,T,E>(owner:&mut X,grant:RetainedCloneGrant,mut run:impl FnMut(&mut X,&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<T,E>)->(Result<T,E>,(usize,usize),u128){let mut captured=None;let(_,heap,work)=turn_ref(owner,grant,|x,_,effect,reply|{captured=Some(run(x,effect).result);Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))});(captured.expect("producer action ran"),heap,work)}
